syntax:
numbers = [1, 2, 3, 4, 5]

# for: iterate over a sequence
for n in numbers:
    print(n)

# range(): generate a sequence of numbers without building a list
for i in range(5):        # 0, 1, 2, 3, 4
    print(i)
for i in range(2, 5):      # 2, 3, 4 - start, stop (exclusive)
    print(i)

# enumerate(): get both the index and the value while iterating
for index, value in enumerate(numbers):
    print(index, value)

# accumulator pattern: build up a result across iterations
total = 0
for n in numbers:
    total += n

# while: repeat while a condition holds
count = 0
while count < 3:
    print(count)
    count += 1

# loop control
for n in numbers:
    if n == 3:
        continue    # skip the rest of this iteration, go to the next
    if n == 5:
        break         # stop the loop entirely
    print(n)

# nested loops: a loop inside another loop, e.g. for a grid
for row in range(3):
    for col in range(3):
        print(row, col)

syntax_fr:
numbers = [1, 2, 3, 4, 5]

# for : itérer sur une séquence
for n in numbers:
    print(n)

# range() : générer une séquence de nombres sans construire de liste
for i in range(5):        # 0, 1, 2, 3, 4
    print(i)
for i in range(2, 5):      # 2, 3, 4 - début, fin (exclue)
    print(i)

# enumerate() : obtenir à la fois l'indice et la valeur pendant l'itération
for index, value in enumerate(numbers):
    print(index, value)

# motif accumulateur : construire un résultat au fil des itérations
total = 0
for n in numbers:
    total += n

# while : répéter tant qu'une condition est vraie
count = 0
while count < 3:
    print(count)
    count += 1

# contrôle de boucle
for n in numbers:
    if n == 3:
        continue    # passe le reste de cette itération, va à la suivante
    if n == 5:
        break         # arrête complètement la boucle
    print(n)

# boucles imbriquées : une boucle à l'intérieur d'une autre, par exemple pour une grille
for row in range(3):
    for col in range(3):
        print(row, col)
